(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035-t*0.5)*8 + Math.cos((y+w1y)*0.025+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.03+t*0.45)*8 + Math.sin((x+w1x)*0.028-t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+4)*40,0.11,2.1],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+1)*50,0.085,1.8]
  ];
  let aS=0,iS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
  }
  const act=aS/8,inh=iS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*1.5)*Math.cos(sy*0.06-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2-t*0.8)*0.5+Math.sin(dist*0.03+ang*6-t*2.0)*0.3)*0.3;
  const cross=Math.sin(act*2.5+inh*1.8+t*0.3)*0.3+Math.cos(act-inh*2.1+t*0.5)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+cross)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*1.3)*0.3)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+sy*0.3+t*3)*Math.sin(sx*0.35-sy*0.45-t*2.5)*0.12;
  const pulse=1.0+Math.sin(dist*0.03-t*2)*0.15*Math.exp(-dist*0.005);
  const blend=(reaction*0.6+cell*0.25+micro*0.15)*pulse;
  const v=Math.max(0,Math.min(1,blend*0.5+0.5+Math.sin(t*0.12)*0.04));
  const pal=[[5,12,58],[12,45,95],[18,95,115],[25,150,135],[120,190,100],[210,195,60],[220,130,65],[195,70,60],[140,35,70],[70,20,60],[25,15,55],[5,12,58]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const vig=1.0-((x-cx)/480)**2*0.3-((y-cy)/240)**2*0.3;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0
  ];
}
